function h(e){const i=[],t={};for(const n of e){const u=Number(n.max_push_amount??0);u>0&&(i.push(n.purchase_receipt_item_id),t[n.purchase_receipt_item_id]=u)}return{selectedItemIds:i,amounts:t}}function l(e,i){let t=0;for(const n of e)t+=Number(i[n]??0);return Math.round(t*100)/100}function f(e,i){return e.map(t=>({purchase_receipt_item_id:t,amount:Number(i[t]??0)})).filter(t=>t.amount>0)}function _(e,i,t){const n=Math.round(Number(t)*100)/100;if(!(n>0)||e.length===0)return{};const u=new Map(i.map(o=>[o.purchase_receipt_item_id,Number(o.max_push_amount??0)])),a=new Map(i.map(o=>[o.purchase_receipt_item_id,Number(o.line_no??0)])),s=[...e].sort((o,m)=>(a.get(o)??0)-(a.get(m)??0));let c=n;const r={};for(const o of s){if(c<=0){r[o]=0;continue}const m=Math.max(0,u.get(o)??0),p=Math.min(m,c);r[o]=Math.round(p*100)/100,c=Math.round((c-p)*100)/100}return r}function d(e,i,t,n){const u=Math.round(Number(t)*100)/100;if(n&&e.length>0){const r=l(e,n);if(Math.abs(r-u)<=.009){const o=e.filter(m=>Number(n[m]??0)>0);return{selectedItemIds:o,amounts:n,payload:f(o,n),lineSum:r}}}const a=_(e,i,u),s=e.filter(r=>Number(a[r]??0)>0),c=l(s,a);return{selectedItemIds:s,amounts:a,payload:f(s,a),lineSum:c}}export{h as i,d as r,l as s};
